module coke_mix(input clk, input rst_n, input start, input [9:0] n, input [3:0] k, input [15:0] types_data, output reg [9:0] result, output reg done); reg [2:0] state; parameter IDLE = 3'd0, INIT = 3'd1, PROCESSING = 3'd2, CALCULATE = 3'd3, DONE = 3'd4; always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= IDLE; result <= 10'd0; done <= 1'b0; end else begin case (state) IDLE: begin if (start) state <= INIT; end INIT: begin state <= PROCESSING; done <= 1'b1; result <= 10'd0; end PROCESSING: begin end CALCULATE: begin end DONE: begin end endcase end end endmodule